fields.InputDefinition:
{
  "goal": "Open the 'Events' entity via the LEFT sidebar 'Search entities...' box, click an event row, then click 'Open Full Record'. In the form toolbar click the history (clock) button to open the Record Changes timeline drawer. Then walk these sections IN ORDER, and as you arrive at each set \"checkpointReached\" to the exact checkpoint name shown: (1) history-filter-pills - the drawer shows a timeline plus filter pills ('All' + one conditional pill per change type with counts); click a conditional pill to narrow the timeline to that change type, then click 'All' to restore (if the record has no history, a clear empty state counts); (2) restore-preview - where a historical change entry and its Restore action exist, click Restore to open the restore preview panel showing the field values that would be restored (do NOT confirm the restore; empty-state also counts); (3) version-label-wizard - near the top find the 'Version Labels' area with its 'Create a version label for this record' button (or a 'No version labels' empty state), and click it to open the version-label creation wizard (do NOT complete/save the label). Keep going until every section has been visited. Pages can take 10-30s to load in this resource-constrained environment - wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "history-filter-pills",
      "instruction": "open the Record Changes drawer and use the type/source filter pills",
      "visualCriteria": [
        "The Record Changes drawer is open showing a timeline plus filter pills (an 'All' pill and type-specific pills with counts); selecting a conditional pill narrows the timeline to that change type and re-selecting 'All' restores the full list - OR a clear no-history empty state is shown"
      ]
    },
    {
      "name": "restore-preview",
      "instruction": "invoke Restore on a historical change to open the restore preview",
      "visualCriteria": [
        "Invoking the Restore action on a historical change entry opens a restore preview panel showing the field values to be restored - OR a clear no-history empty state is shown"
      ]
    },
    {
      "name": "version-label-wizard",
      "instruction": "open the create-version-label wizard from the Version Labels area",
      "visualCriteria": [
        "The drawer shows a 'Version Labels' area (existing labels or a 'No version labels' empty state) and clicking the create-version-label button opens the label-creation wizard/form"
      ]
    }
  ]
}
